n=17; center=8
out=[]
for r in range(n):
    row=[0]*n
    if r<=center:
        left,right=center-r,center+r
        row[left]=row[right]=2
        for c in range(left,right+1):
            if c%4==r%4 and row[c]==0:
                row[c]=1
    else:
        for c in range(n):
            if c%4==r%4:
                row[c]=1
    out.append(row)
import json
print(json.dumps(out))

